-- WhatsApp CRM production runtime closure. Provider delivery remains explicitly gated by crm_provider_configs.
create table if not exists public.crm_whatsapp_conversations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,property_id uuid,customer_id uuid not null,phone_number text,assigned_to uuid,status text not null default 'open',last_message_at timestamptz,last_inbound_at timestamptz,last_outbound_at timestamptz,opt_in_status text not null default 'unknown',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists crm_whatsapp_conv_scope_idx on public.crm_whatsapp_conversations(tenant_id,property_id,customer_id,last_message_at desc);
create table if not exists public.crm_whatsapp_messages(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,property_id uuid,conversation_id uuid not null references public.crm_whatsapp_conversations(id) on delete cascade,customer_id uuid not null,direction text not null,message_type text not null default 'text',body text,media_url text,template_id uuid,provider_message_id text,status text not null default 'queued',error_code text,error_message text,idempotency_key text,created_at timestamptz not null default now(),sent_at timestamptz,delivered_at timestamptz,read_at timestamptz,failed_at timestamptz);
create unique index if not exists crm_whatsapp_messages_idem_uq on public.crm_whatsapp_messages(tenant_id,idempotency_key) where idempotency_key is not null;
create unique index if not exists crm_whatsapp_provider_id_uq on public.crm_whatsapp_messages(tenant_id,provider_message_id) where provider_message_id is not null;
create table if not exists public.crm_whatsapp_jobs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,property_id uuid,conversation_id uuid references public.crm_whatsapp_conversations(id) on delete set null,message_id uuid references public.crm_whatsapp_messages(id) on delete cascade,job_type text not null default 'send',status text not null default 'queued',attempts integer not null default 0,max_attempts integer not null default 5,next_attempt_at timestamptz not null default now(),last_error text,created_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists crm_whatsapp_jobs_queue_idx on public.crm_whatsapp_jobs(status,next_attempt_at);
create table if not exists public.crm_whatsapp_optouts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,property_id uuid,customer_id uuid not null,phone_number text,source text,reason text,created_at timestamptz not null default now());
create unique index if not exists crm_whatsapp_optout_customer_uq on public.crm_whatsapp_optouts(tenant_id,customer_id);
create table if not exists public.crm_whatsapp_delivery_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,property_id uuid,message_id uuid references public.crm_whatsapp_messages(id) on delete cascade,provider_message_id text,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists crm_whatsapp_delivery_events_uq on public.crm_whatsapp_delivery_events(tenant_id,provider_message_id,event_type);
do $$ declare t text; begin foreach t in array array['crm_whatsapp_conversations','crm_whatsapp_messages','crm_whatsapp_jobs','crm_whatsapp_optouts','crm_whatsapp_delivery_events'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists %I on public.%I',t||'_scope',t); execute format('create policy %I on public.%I for all to authenticated using(anaira_can_access_tenant(tenant_id)) with check(anaira_can_access_tenant(tenant_id))',t||'_scope',t); end loop; end $$;
create or replace function public.anaira_whatsapp_enqueue(p_customer_id uuid,p_phone text,p_body text,p_message_type text default 'text',p_template_id uuid default null,p_property_id uuid default null,p_idempotency_key text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare c public.crm_whatsapp_conversations%rowtype; m public.crm_whatsapp_messages%rowtype; q public.crm_whatsapp_jobs%rowtype; tid uuid; connected boolean; begin select tenant_id into tid from public.crm_customers where id=p_customer_id; if tid is null or not anaira_can_access_tenant(tid) then raise exception 'Unauthorized or customer not found'; end if; if p_idempotency_key is not null then select * into m from public.crm_whatsapp_messages where tenant_id=tid and idempotency_key=p_idempotency_key; if found then return jsonb_build_object('ok',true,'duplicate',true,'message_id',m.id,'status',m.status); end if; end if; if p_message_type='marketing' and exists(select 1 from public.crm_whatsapp_optouts where tenant_id=tid and customer_id=p_customer_id) then raise exception 'WhatsApp marketing opt-out active'; end if; select * into c from public.crm_whatsapp_conversations where tenant_id=tid and customer_id=p_customer_id and property_id is not distinct from p_property_id order by updated_at desc limit 1; if c.id is null then insert into public.crm_whatsapp_conversations(tenant_id,property_id,customer_id,phone_number) values(tid,p_property_id,p_customer_id,p_phone) returning * into c; end if; connected:=exists(select 1 from public.crm_provider_configs where tenant_id=tid and channel='whatsapp' and enabled=true); insert into public.crm_whatsapp_messages(tenant_id,property_id,conversation_id,customer_id,direction,message_type,body,template_id,status,idempotency_key) values(tid,p_property_id,c.id,p_customer_id,'outbound',p_message_type,p_body,p_template_id,case when connected then 'queued' else 'not_connected' end,p_idempotency_key) returning * into m; if connected then insert into public.crm_whatsapp_jobs(tenant_id,property_id,conversation_id,message_id) values(tid,p_property_id,c.id,m.id) returning * into q; end if; update public.crm_whatsapp_conversations set last_message_at=now(),last_outbound_at=now(),updated_at=now() where id=c.id; insert into public.crm_message_log(tenant_id,property_id,customer_id,channel,direction,template_id,status,payload) values(tid,p_property_id,p_customer_id,'whatsapp','outbound',p_template_id,case when connected then 'queued' else 'not_connected' end,jsonb_build_object('message_id',m.id,'body',p_body)); insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(tid,p_property_id,'whatsapp_enqueued','crm_whatsapp_messages',m.id,to_jsonb(m)); return jsonb_build_object('ok',true,'message_id',m.id,'conversation_id',c.id,'status',m.status,'provider_connected',connected); end $$;
revoke all on function public.anaira_whatsapp_enqueue(uuid,text,text,text,uuid,uuid,text) from public; grant execute on function public.anaira_whatsapp_enqueue(uuid,text,text,text,uuid,uuid,text) to authenticated;
create or replace function public.anaira_whatsapp_apply_status(p_provider_message_id text,p_status text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare m public.crm_whatsapp_messages%rowtype; ns text:=lower(p_status); begin select * into m from public.crm_whatsapp_messages where provider_message_id=p_provider_message_id for update; if not found then raise exception 'Provider message not found'; end if; if not anaira_can_access_tenant(m.tenant_id) then raise exception 'Unauthorized'; end if; update public.crm_whatsapp_messages set status=ns,sent_at=case when ns='sent' then coalesce(sent_at,now()) else sent_at end,delivered_at=case when ns='delivered' then coalesce(delivered_at,now()) else delivered_at end,read_at=case when ns='read' then coalesce(read_at,now()) else read_at end,failed_at=case when ns='failed' then coalesce(failed_at,now()) else failed_at end,error_message=case when ns='failed' then coalesce(p_payload->>'error',error_message) else error_message end where id=m.id returning * into m; insert into public.crm_whatsapp_delivery_events(tenant_id,property_id,message_id,provider_message_id,event_type,payload) values(m.tenant_id,m.property_id,m.id,p_provider_message_id,ns,p_payload) on conflict do nothing; insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(m.tenant_id,m.property_id,'whatsapp_status_'||ns,'crm_whatsapp_messages',m.id,to_jsonb(m)); return jsonb_build_object('ok',true,'message_id',m.id,'status',m.status); end $$;
revoke all on function public.anaira_whatsapp_apply_status(text,text,jsonb) from public; grant execute on function public.anaira_whatsapp_apply_status(text,text,jsonb) to authenticated;
create or replace function public.anaira_whatsapp_optout(p_customer_id uuid,p_phone text default null,p_reason text default null,p_property_id uuid default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare tid uuid; begin select tenant_id into tid from public.crm_customers where id=p_customer_id; if tid is null or not anaira_can_access_tenant(tid) then raise exception 'Unauthorized'; end if; insert into public.crm_whatsapp_optouts(tenant_id,property_id,customer_id,phone_number,source,reason) values(tid,p_property_id,p_customer_id,p_phone,'crm',p_reason) on conflict(tenant_id,customer_id) do update set reason=excluded.reason,created_at=now(); insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(tid,p_property_id,'whatsapp_optout','crm_whatsapp_optouts',p_customer_id,jsonb_build_object('reason',p_reason)); return jsonb_build_object('ok',true,'opted_out',true); end $$;
revoke all on function public.anaira_whatsapp_optout(uuid,text,text,uuid) from public; grant execute on function public.anaira_whatsapp_optout(uuid,text,text,uuid) to authenticated;
create or replace function public.anaira_whatsapp_job_worker(p_limit integer default 50) returns integer language plpgsql security definer set search_path=public,pg_temp as $$ declare j record; n integer:=0; connected boolean; begin for j in select q.*,m.id as mid from public.crm_whatsapp_jobs q join public.crm_whatsapp_messages m on m.id=q.message_id where q.status='queued' and q.next_attempt_at<=now() order by q.created_at limit p_limit for update of q skip locked loop connected:=exists(select 1 from public.crm_provider_configs where tenant_id=j.tenant_id and channel='whatsapp' and enabled=true); if not connected then update public.crm_whatsapp_jobs set status='failed',attempts=attempts+1,last_error='WhatsApp provider not connected' where id=j.id; update public.crm_whatsapp_messages set status='not_connected',error_message='WhatsApp provider not connected' where id=j.mid; else update public.crm_whatsapp_jobs set status='processing',attempts=attempts+1 where id=j.id; update public.crm_whatsapp_messages set status='provider_pending' where id=j.mid; end if; n:=n+1; end loop; return n; end $$;
revoke all on function public.anaira_whatsapp_job_worker(integer) from public; grant execute on function public.anaira_whatsapp_job_worker(integer) to service_role;
